   //"lexp"
   
   Stack<lam_class> lam_cls_stack = new Stack<>();

   public R visit(LambdaExpression n, A argu) {
      R _ret=null;
      
      in_lambda++;
      String arg = n.f1.f0.toString();
      
      //have to add stack for following 3 fields also for handling nested lambdas
      lam_class curr_lam_cls = new lam_class();

      // curr_lambda_apply = new String();
      String new_obj = gen_temp();
      String label = gen_lambda_label();

      HashMap<String,Variable> curr_scope = scopes.peek();
      curr_scope.put(arg,new Variable(lambda_arg_type,arg,"TEMP -1"));

      // ArrayList<String> curr_obj_offset = new ArrayList<>();

      curr_lam_cls.obj_offset.add("vtable ");
      curr_lam_cls.obj_offset.add("this class point");

      curr_lam_cls.apply = label+" [ 2 ] \n";
      curr_lam_cls.apply += BEGIN + RETURN;

      lam_cls_stack.push(curr_lam_cls);

      // n.f1.accept(this, argu); //arg (identifier)
      n.f2.accept(this, argu);
      n.f3.accept(this, argu);
      n.f4.accept(this, argu);

      curr_lam_cls = lam_cls_stack.peek();
      ArrayList<String> curr_obj_offset = curr_lam_cls.obj_offset;
      curr_scope = scopes.peek();
      String code = "";
      Integer sz = (curr_lam_cls.obj_offset.size())*4;
      
      code += BEGIN;
         code += MOVE + new_obj + HALLOCATE + sz.toString()+endl;
         code += HSTORE + new_obj + " 0 " +  label + "\n";
         code += HSTORE + new_obj + " 4 " + " TEMP 0 " + "\n";
         
         for(int i = 2;i<curr_obj_offset.size();i++){
            String temp = curr_scope.get(curr_obj_offset.get(i)).temp;
            Integer j = i*4;
            code += HSTORE + new_obj + j.toString() + " " + temp + "\n";
         }
      code += RETURN + new_obj;
      code += END;

      curr_lam_cls.apply += END;

      lam_cls_stack.pop();
      curr_scope.remove(arg);
      lambda_functions.add(curr_lam_cls.apply);
      in_lambda--;

      println_translation(code);
      
      return _ret;
   }

