   /**
    * f0 -> <IDENTIFIER>
    */
   //"iden"
   public R visit(Identifier n, A argu) {
      R _ret=null;
      
      if(in_type){
         if(n.f0.toString().equals("Integer")) return (R)INT;
         if(n.f0.toString().equals("Boolean")) return (R)BOOL;
         return (R)n.f0.toString();
      }

      String iden = n.f0.toString();
      if(scopes == null){
         println_translation("scopes null "+curr_class_name + " ::" + curr_method_name);
         // throw new RuntimeException();
      }
      HashMap<String,Variable> curr_scope = scopes.peek();

      
      if(curr_scope.containsKey(iden)){
         
         Variable v = curr_scope.get(iden);
         
         //if its a lambda argument then it is in curr_scope with TEMP -1
         if(v.temp.equals("TEMP -1")){
            println_translation(TEMP+"1");
            return (R)v.type;
         }

         if(in_lambda == 0)
            print_translation(v.temp + " ");
         else{
            lam_class curr_lam_cls = lam_cls_stack.peek();
            ArrayList<String> lam_obj_offset = curr_lam_cls.obj_offset;
            Integer offset;
            String code = "";

            if(lam_obj_offset.contains(iden)) offset = lam_obj_offset.indexOf(iden);
            else{
               lam_obj_offset.add(iden);
               offset = lam_obj_offset.size() - 1;
            } 
            
            offset = offset*4;
            code += BEGIN;
               code += HLOAD + v.temp + TEMP + " 0 "+ offset.toString()+endl;
            code += RETURN + v.temp;
            code += END;
            println_translation(code);
         }
         return (R) v.type;
      }
      else {
         if(curr_method_name.isEmpty()) throw new RuntimeException();
         ClassInfo c = classes.get(curr_class_name);
         Integer offset = get_offset(c.variables, iden);

         offset = offset*4;

         String final_val = gen_temp();

         String this_pointer = " TEMP 0 ";
         if(in_lambda != 0) 
         {
            // System.err.println(iden+" "+offset+" "+curr_method_name);
            this_pointer = final_val;
         }

         String code = BEGIN;
            if(in_lambda!=0) code += HLOAD + final_val + " TEMP 0 4 \n";
            code += HLOAD + final_val + this_pointer + "4 \n";
            code += HLOAD + final_val + final_val + offset.toString() + space + "\n";   
            code += RETURN + final_val + endl;
         code += END;
         print_translation(code);

         String type = get_type_var(c, iden);
         
         // System.err.println("in iden+"+iden+" "+type);
         return (R)type;
      }

      // return (R)n.f0.toS//tring();
   }

